-- Idempotent charge: unique key makes a duplicate insert fail instead of double-charging
CREATE TABLE idempotency_keys (
  key         UUID PRIMARY KEY,
  status      TEXT,          -- in_progress | completed
  response    JSONB,
  created_at  TIMESTAMP DEFAULT now()
);

BEGIN;
  INSERT INTO idempotency_keys(key, status) VALUES ($1, 'in_progress'); -- fails if retried
  -- ... perform charge, then:
  UPDATE idempotency_keys SET status='completed', response=$2 WHERE key=$1;
COMMIT;
-- On a duplicate key violation: SELECT response FROM idempotency_keys WHERE key=$1;

// API gateway: authenticate, rate-limit, then route via service discovery
async function handle(req) {
  const user = await auth.verify(req.headers.authorization); // 1) auth
  if (!await limiter.allow(user.id)) return resp(429);       // 2) rate limit
  const target = req.path.split('/')[1];                     // e.g. 'orders'
  const node = await discovery.pick(target);                 // 3) find healthy instance
  return proxy(node, req);                                    // 4) route
}
